<?php
declare(strict_types=1);
define('BASE_PATH',dirname(__DIR__));require BASE_PATH.'/app/Support/helpers.php';spl_autoload_register(static function(string $class):void{$prefix='App\\';if(str_starts_with($class,$prefix))require BASE_PATH.'/app/'.str_replace('\\','/',substr($class,strlen($prefix))).'.php';});
use App\Import\CourseImportService;
$config=require BASE_PATH.'/config/database.php';$testDb='gbu_course_import_'.bin2hex(random_bytes(4));$server=new PDO("mysql:host={$config['host']};port={$config['port']};charset=utf8mb4",$config['username'],$config['password'],[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_EMULATE_PREPARES=>true]);$csv=tempnam(sys_get_temp_dir(),'course_import_');
try{$schema=str_replace('gbu_exam_operations',$testDb,file_get_contents(BASE_PATH.'/database/schema.sql'));$server->exec($schema);$seed=str_replace('gbu_exam_operations',$testDb,file_get_contents(BASE_PATH.'/database/seed.sql'));$server->exec($seed);$pdo=new PDO("mysql:host={$config['host']};port={$config['port']};dbname={$testDb};charset=utf8mb4",$config['username'],$config['password'],[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC]);$pdo->exec("INSERT INTO users(role_id,username,password_hash,name,status) SELECT id,'course_test','test','Course Test','active' FROM roles WHERE code='admin'");$user=(int)$pdo->lastInsertId();file_put_contents($csv,"Course Code,Course Name,Programme Code,Semester,Category,Status\nCS-101,Programming Fundamentals,UCS,1,core,active\nCS-102,Discrete Mathematics,UCS,1,core,active\nBAD,Invalid Semester,UCS,99,core,active\n");$service=new CourseImportService($pdo);$batch=$service->stage($csv,'courses.csv',$user);$summary=$pdo->query("SELECT total_rows,valid_rows,invalid_rows FROM import_batches WHERE id={$batch}")->fetch();assert((int)$summary['total_rows']===3&&(int)$summary['valid_rows']===2&&(int)$summary['invalid_rows']===1);$pdo->beginTransaction();$count=$service->commit($batch,$user);$pdo->commit();assert($count===2);assert((int)$pdo->query("SELECT COUNT(*) FROM programme_courses pc JOIN courses c ON c.id=pc.course_id WHERE c.code IN ('CS-101','CS-102') AND pc.semester=1")->fetchColumn()===2);echo "Course import: PASS (branch, semester, validation, curriculum commit)\n";}finally{if(is_file($csv))unlink($csv);$server->exec("DROP DATABASE IF EXISTS `{$testDb}`");}
